fy_drift', 'probe': None}], 'verification': {'what': 'service health', 'how': 'monitor service state', 'expected': 'all services running'}, 'rollback': {'trigger': 'remediation fails', 'action': 'revert to previous config', 'safety_guard': 'validate service status', 'restores_state': ['previous configuration state'], 'restoration_evidence': 'confirmation of service status post-reversion'}, 'risk_class': 'critical', 'blast_radius': 'medium', 'satisfies': None}, {'id': 'generate_report', 'description': 'Generate a report of drift status and remediation', 'action': 'compile findings', 'target': 'drift report', 'parallel_group': None, 'preconditions': [{'description': 'remediation completed', 'fact': 'remediation_status', 'established_by': 'remediate_drift', 'probe': None}], 'verification': {'what': 'report contents', 'how': 'review generated report', 'expected': 'accurate report reflecting drift and remediation'}, 'rollback': {'trigger': 'report generation fails', 'action': 'notify admin of report issue', 'safety_guard': 'ensure fallback communication', 'restores_state': ['previous reporting state'], 'restoration_evidence': 'confirmation of admin notification'}, 'risk_class': 'medium', 'blast_radius': 'medium', 'satisfies': None}], 'dependencies': [{'from_task': 'detect_drift', 'to_task': 'classify_drift', 'kind': 'hard', 'reason': ''}, {'from_task': 'classify_drift', 'to_task': 'remediate_drift', 'kind': 'hard', 'reason': ''}, {'from_task': 'remediate_drift', 'to_task': 'generate_report', 'kind': 'hard', 'reason': ''}], 'branches': []}

